tasks=[]
def q(id,prompt,options,answer,explanation,stimulus=None,group=None):
    return dict(id=id,prompt=prompt,options=options,answer=answer,explanation=explanation,**({'stimulus':stimulus} if stimulus else {}),**({'group':group} if group else {}))
def task(id,skill,order,level,title,instruction,stimulus,questions,**kw):
    tasks.append(dict(id=id,skill=skill,order=order,level=level,title=title,instruction=instruction,stimulus=stimulus,questions=questions,**kw))

