    gapqs.append(q(f'cl4-{i+1}',f'Hueco [{i+1}] · Texto {"AB"[group]}',gap_options[group],i%4,'El fragmento enlaza con el problema o la consecuencia desarrollados en el párrafo.',group='AB'[group]))
