for i,(opts,a,e) in enumerate(clozedata,1):
    shift=i%3; rotated=opts[shift:]+opts[:shift]
    clozeqs.append(q(f'cl5-{i}',f'Hueco [{i}]',rotated,(a-shift)%3,e))
