task('eio-3','oral',3,'B1','Resolver dos situaciones','Selecciona una situación personal y otra pública. Explica el problema, pide o proporciona información y propone una solución.','',[],choices=[{'title':'Personal A · Cambiar un plan','stimulus':'Habías quedado con una amiga para estudiar. Te han cambiado el horario de prácticas. Deja un mensaje, explica el cambio y propone otra fecha.'},{'title':'Personal B · Pedir ayuda','stimulus':'No puedes asistir a una reunión de grupo. Pide a un compañero que te informe de los acuerdos y ofrece una forma de contribuir.'},{'title':'Pública A · Solicitar información','stimulus':'Llama a un centro cultural para organizar una visita con tu clase. Pregunta por horarios, coste y actividades adecuadas.'},{'title':'Pública B · Resolver una incidencia','stimulus':'Has reservado una sala para un taller, pero está ocupada. Explica la situación a recepción y solicita una alternativa.'}],prompts=['Responde a la situación personal elegida.','Responde a la situación pública elegida.'],preparation=30,duration=60)
topicA='Algunos centros educativos quieren reservar una parte de la semana para proyectos en los que el alumnado elija un problema de su entorno y trabaje en equipo para investigarlo. Sus defensores consideran que así se relacionan los contenidos con situaciones reales y se desarrollan habilidades de cooperación. Otros docentes señalan que la autonomía exige apoyos, tiempo y criterios claros para no aumentar las desigualdades de participación. El debate plantea cómo combinar una estructura común con oportunidades de decisión y cómo reconocer la contribución individual dentro de un producto colectivo.'
topicB='Las herramientas de inteligencia artificial permiten producir borradores, resumir textos y recibir comentarios de manera inmediata. En las clases de idiomas pueden abrir oportunidades para practicar, pero también suscitan dudas sobre dependencia, privacidad y autoría. Algunos profesores proponen enseñar a contrastar sus respuestas y a explicar las decisiones tomadas al utilizarlas. Otros consideran preferible limitar su presencia mientras se desarrollan habilidades básicas. La cuestión incluye cómo evaluar una producción cuando ha habido ayuda tecnológica y qué condiciones permitirían usar esa ayuda de forma transparente y responsable.'
task('eio-4','oral',4,'B2','Opinar y explicar','Elige un tema, lee el texto y responde a tres preguntas. La tarea siguiente conservará el tema elegido.','',[],choices=[{'title':'A · Autonomía y proyectos','stimulus':topicA},{'title':'B · IA en el aprendizaje','stimulus':topicB}],prompts=['¿Qué ventajas y dificultades ves en dar más autonomía al alumnado?','¿Cómo evitarías que en un grupo unas personas participen más que otras?','¿Qué evidencia buscarías para valorar si un proyecto ayuda a aprender?'],alternativePrompts=['¿Qué oportunidades y riesgos ves en utilizar IA para aprender idiomas?','¿Cómo explicarías a tus alumnos un uso responsable de estas herramientas?','¿Qué cambiarías en la evaluación para reconocer el aprendizaje propio?'],preparation=30,duration=60)
